import re
lines = current_frame.ascii.split('\n')
def cells(color):
    out=[]
    for r,l in enumerate(lines):
        for c,ch in enumerate(l):
            if ch==color: out.append((r,c))
    return out
Y=cells('Y'); b=cells('b'); W=cells('W'); c=cells('c'); p=cells('p')
def bbox(px):
    rs=[x[0] for x in px]; cs=[x[1] for x in px]
    return (min(rs),min(cs),max(rs),max(cs))
print("Y bbox",bbox(Y),len(Y))
print("b bbox",bbox(b),len(b))
# rows of yellow
for r in range(14,30):
    row=[c for (rr,c) in Y if rr==r]
    if row: print("Y row",r,row)
"}

