def cov2(kind,a,b,t,L):
    r,c=t
    if kind=='diam': return abs(r-a)+abs(c-b)==L
    if kind=='x': return abs(r-a)==abs(c-b) and abs(r-a)<=L
    return (r==a) or (c==b)
